-- Seed data para competencias específicas de 2do Grado del Nivel Secundario
-- Documento oficial: Adecuación Curricular Nivel Secundario - Primer Ciclo (Páginas 130-147)

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española (Páginas 130-131)
('Secundaria', '2do', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Comunica sus ideas y experiencias en diferentes situaciones, mediante un género textual (funcional o literario) abordado desde la comprensión y producción oral y escrita, mostrando creatividad y destrezas en el uso de la lengua, utilizando medios y recursos tecnológicos y de otros tipos.'),
('Secundaria', '2do', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Produce textos orales y escritos variados a partir de inferencias de comprensión y producción textual, demostrando un pensamiento estructurado, derivando en conclusiones razonables y lógicas.'),
('Secundaria', '2do', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Utiliza textos específicos variados (orales y escritos) que apoyan el desarrollo de una investigación de carácter científico, seleccionando información con criterios de relevancia, pertinencia, validez y confiabilidad.'),
('Secundaria', '2do', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Usa textos variados de secuencia argumentativa, con los que conoce y cuestiona prácticas sociales de ciudadanía en el entorno local, nacional e internacional, confrontándolas con los valores universales en discursos analíticos y propositivos.'),
('Secundaria', '2do', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Utiliza textos literarios como manifestación de la lengua y recurso para promover valores universales y fortalecer la dimensión humanista.'),
('Secundaria', '2do', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Utiliza textos de secuencia expositivo-explicativa de manera oral y escrita, en la divulgación de hallazgos científicos y sociales, así como de los avances tecnológicos a lo largo del tiempo, haciendo uso de variadas herramientas que proporcionan las tecnologías de la información y la comunicación TIC.'),
('Secundaria', '2do', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Usa textos diversos en la divulgación y promoción de situaciones de salud y ambiente, abordando temas y problemas de actualidad, mediante el uso de herramientas tecnológicas, entre otras.'),

-- Lenguas Extranjeras - Inglés (Páginas 132-133)
('Secundaria', '2do', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación, utilizando el idioma inglés de forma breve y sencilla con la finalidad de informar, ofrecer ayuda, sugerir, comprar, describir planes futuros, y narrar experiencias, con relación a necesidades concretas y temas cotidianos.'),
('Secundaria', '2do', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Interactúa de forma oral y escrita en el idioma inglés empleando razonamiento lógico-verbal y estrategias de desempeño de manera creativa y crítica en distintas situaciones de comunicación donde narra experiencias, da sugerencias y consejos y expresa planes en expresiones breves y sencillas.'),
('Secundaria', '2do', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Interactúa en inglés ante diversas circunstancias y problemas comunes de su entorno inmediato en las que solicita u ofrece ayuda, da consejos y sugerencias pertinentes y emplea estrategias de desempeño oral y escrito para lograr la claridad del mensaje, aunque el interlocutor deba hacer cierto esfuerzo oral y escrito para comprenderle.'),
('Secundaria', '2do', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se comunica en el idioma inglés de forma breve y sencilla, con cortesía y respeto, reconociendo las diferencias individuales más comunes, y la identidad social y cultural propias de la comunidad local y global.'),
('Secundaria', '2do', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Interactúa en el idioma inglés, con cortesía, honestidad, actitud de respeto y aceptación al referirse a sí mismo/a y a las demás personas, al hacer sugerencias y al describir experiencias, planes, estados anímicos y físicos.'),
('Secundaria', '2do', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Se comunica en el idioma inglés con el propósito de solicitar y ofrecer ayuda, expresar interés y dar sugerencias sobre asuntos científicos, tecnológicos y de otra índole, en situaciones inmediatas de comunicación.'),
('Secundaria', '2do', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Muestra preferencia por opciones que impactan positivamente la salud y el medio ambiente al interactuar en inglés sobre sus actividades cotidianas y en situaciones de compra, así como al describir estados anímicos y físicos.'),

-- Lenguas Extranjeras - Francés (Páginas 134-135)
('Secundaria', '2do', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Se comunica en francés utilizando frases y oraciones básicas, breves y sencillas, previamente ensayadas, relativas a temas cotidianos y en situaciones inmediatas de comunicación, donde comparte información personal básica, expresa preferencias, describe viviendas y actividades cotidianas, necesitando que le repitan o releyendo cuando sea necesario.'),
('Secundaria', '2do', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Se comunica en el idioma francés, utilizando la lógica verbal para estructurar un repertorio limitado de frases y expresiones básicas que practica y presenta en distintas situaciones de comunicación de forma creativa previamente planificadas e interactuadas con su interlocutor/a.'),
('Secundaria', '2do', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Comprende y expresa informaciones relevantes para resolver problemas y necesidades inmediatas de comunicación en su entorno cotidiano, tales como la identificación y descripción de personas, datos personales, gustos y preferencias, viviendas y actividades cotidianas propias y de otros, utilizando frases hechas y oraciones muy breves y sencillas, con la ayuda de su interlocutor para poder expresarse y poder ser comprendido.'),
('Secundaria', '2do', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE-LEF4', 'Se comunica con cortesía y respeto durante intercambios básicos orales y escritos, identificando las diferencias y semejanzas individuales básicas y la identidad social y cultural propia y de otras personas, relativas a las profesiones, actividades cotidianas y recreativas, la familia, la vivienda, los gustos y preferencias.'),
('Secundaria', '2do', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Se identifica e identifica a otras personas en el idioma francés, en un plano de cortesía actitud de respeto, honestidad y aceptación, al compartir informaciones personales básicas, tales como preferencias y viviendas, y al describir actividades cotidianas.'),
('Secundaria', '2do', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Identifica, organiza y comparte en formato físico, digital o en línea, información relativa a la ciencia y la tecnología presentes en su entorno cotidiano, haciendo uso de un repertorio limitado de vocabulario, frases y oraciones muy breves y sencillas que requiere esfuerzo para ser comprendido.'),
('Secundaria', '2do', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Expresa preferencia por opciones que impactan positivamente la salud y el medioambiente, en distintas situaciones inmediatas de comunicación oral y escrita, donde se identifica a sí mismo y a otras personas, describiendo su entorno, vivienda y actividades cotidianas.'),

-- Matemática (Páginas 136-137)
('Secundaria', '2do', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Elabora conjeturas y argumentos convincentes para presentar y discutir las propias ideas matemáticas.'),
('Secundaria', '2do', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-MAT2', 'Aplica procesos de razonamientos, con especial atención al razonamiento espacial y al razonamiento con proporciones y gráficas para la comprensión e interpretación del entorno.'),
('Secundaria', '2do', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE-MAT3', 'Desarrolla diversas estrategias para resolver problemas del contexto, dentro y fuera de la matemática, interpretando y verificando los resultados en relación con la situación del problema original.'),
('Secundaria', '2do', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Muestra autonomía en la búsqueda de soluciones a situaciones relacionadas con los conocimientos matemáticos, respetando los diferentes criterios de solución de los demás.'),
('Secundaria', '2do', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Muestra autonomía en la búsqueda de soluciones a situaciones de problemas matemáticos, respetando los diferentes criterios de abordaje de sus compañeros.'),
('Secundaria', '2do', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Aplica herramientas tecnológicas para la resolución e interpretación de problemas del entorno y a partir de los conocimientos matemáticos que posee.'),
('Secundaria', '2do', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Aplica modelos matemáticos para estudiar situaciones del medioambiente que afecten la vida de la comunidad escolar.'),

-- Ciencias Sociales (Páginas 138-139)
('Secundaria', '2do', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Compara de manera rigurosa la autoría de fuentes primarias y secundarias consultadas en medios impresos y digitales sobre procesos sociales, políticos, económicos, históricos, geográficos o culturales, con la finalidad de garantizar la credibilidad de las informaciones.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Interpreta por medio de investigaciones realizadas, hechos históricos y su relación con el espacio geográfico, con la finalidad de evaluar críticamente los cambios que se producen en el tiempo y el espacio.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Explica mediante el levantamiento de información, la existencia de un problema social y el contexto en el que se produce, con la finalidad de comprender su incidencia en el tiempo y el espacio.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Promueve proyectos e iniciativas que fomenten una cultura de paz, el respeto por los valores culturales e interculturales, y los derechos humanos, con la finalidad de lograr una convivencia pacífica y armoniosa en la sociedad.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Demuestra su capacidad para valorar y fomentar relaciones equilibradas y armoniosas, con la finalidad de impulsar la formación de una ciudadanía responsable y la defensa de los principios democráticos.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Analiza explicaciones científicas de fenómenos naturales y teorías de fenómenos sociales, mediante el uso de fuentes confiables en sus proyectos de investigación, con la finalidad de sustentar los hallazgos.'),
('Secundaria', '2do', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Argumenta a través de investigaciones sobre las acciones humanas que pueden afectar los estilos de vida saludables y el equilibrio ambiental, con la finalidad de presentar su impacto en la sociedad y en la naturaleza.'),

-- Ciencias de la Naturaleza – Ciencias de la Vida (Páginas 140-141)
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el Lenguaje científico y tecnológico de ciencias de la vida que implica sus ideas básicas a respuestas a preguntas y situaciones de problemas simulados y reales.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones científicas y tecnológicas a problemas y fenómenos naturales relacionados a Ciencias de la Vida.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica procedimientos científicos y tecnológicos, básicos y organizados para solucionar problemas o dar respuestas a fenómenos naturales relacionados con Ciencias de la Vida.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza la naturaleza de las ciencias naturales y el alcance del desarrollo tecnológico en nuestra sociedad relacionada con Ciencias de la Vida, sus aportes y reflexiones éticas.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal desde las Ciencias de la Vida.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones, y les da explicación utilizando ideas y procesos fundamentales de las Ciencias de la Vida y las ingenierías.'),
('Secundaria', '2do', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Actúa con responsabilidad crítica y autónoma para el cuidado de su salud y ambiental relacionada con Ciencias de la Vida.'),

-- Educación Artística (Páginas 142-143)
('Secundaria', '2do', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Argumenta sobre la función de los distintos lenguajes artísticos en la construcción histórica de la sociedad en los contextos.'),
('Secundaria', '2do', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Elabora propuestas artísticas, individuales y colectivas, mediante el uso de referentes estéticos, valorando la importancia del arte como medio de comunicación y transformación social.'),
('Secundaria', '2do', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Utiliza elementos técnicos de distintas expresiones artísticas en sus proyectos personales y colectivos comprendiendo mensaje, forma y contenido.'),
('Secundaria', '2do', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Interpreta y crea piezas utilizando lenguajes artísticos a partir de aspectos sociales del contexto y que reflejan su identidad cultural.'),
('Secundaria', '2do', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Utiliza elementos de los lenguajes artísticos como medio de expresión de su identidad personal, social y cultural.'),
('Secundaria', '2do', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Realiza procesos creativos integrando herramientas tecnológicas como apoyo en producciones artísticas.'),
('Secundaria', '2do', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Analiza el modo de utilización óptima de materiales, recursos y espacios propios de las artes y sus lenguajes en el cuidado de su cuerpo y conducta para la mejora de su salud y la de los distintos ambientes naturales y ecosistemas.'),

-- Educación Física (Páginas 144-145)
('Secundaria', '2do', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Se comunica en su entorno social y cultural, a partir de la realización de actividades motrices en grupo.'),
('Secundaria', '2do', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Domina su acción motriz, a partir de su nivel de percepción y apreciación de patrones, tamaños, formas, direcciones y relaciones espaciales y temporales dinámicas en diversos entornos, con base en la noción de su esquema corporal.'),
('Secundaria', '2do', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Utiliza el desarrollo de distintos niveles de desempeño motriz a partir de sus condiciones físicas naturales, a fin de alcanzar eficacia motora progresiva en situaciones variables (juegos, deportes, trabajo).'),
('Secundaria', '2do', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Muestra dominio en la realización de actividades motrices en grupo, asumiendo su responsabilidad en el trabajo en equipo.'),
('Secundaria', '2do', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Establece relación entre sus actividades corporales y el desarrollo de las habilidades motrices y las capacidades Físicas, con el fin de mantener la motivación y disponibilidad corporal en el juego.'),
('Secundaria', '2do', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Descubre mediante análisis, las características de implementos deportivos específicos, con la finalidad de usarlos en forma efectiva en situaciones de juegos y deportes.'),
('Secundaria', '2do', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Identifica los factores y situaciones de riesgo para su salud, de los demás y de su entorno, para contribuir en el cuidado personal y del medioambiente durante las actividades físicas.'),

-- Formación Integral Humana y Religiosa (Páginas 146-147)
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Establece criterios sobre el respeto a la vida humana en todas sus etapas, a partir de los derechos humanos, los valores éticos y religiosos presentes en su contexto familiar, escolar y social.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Argumenta sobre la práctica de valores vinculados al trabajo, a fin de identificar su aporte al desarrollo de las personas, la familia y la sociedad.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Analiza su realidad familiar y social, tomando en cuenta valores humanos y cristianos, a fin de plantear y promover estrategias de solución a los conflictos.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Constata en la misión de Jesús de Nazaret la manifestación del amor de Dios hacia las personas, con el fin de desarrollar actitudes y acciones que favorezcan el bienestar de los demás.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Reconoce los cambios que experimenta en la etapa de la adolescencia e identifica su influencia en sus intereses y comportamientos, con el propósito de tomar decisiones que favorezcan su desarrollo humano y espiritual.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Explica partir de criterios éticos la contribución de las ciencias y las tecnologías para el desarrollo de la sociedad, la vida humana y el entorno natural.'),
('Secundaria', '2do', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Propone acciones que fomentan el cuidado y sostenibilidad del entorno natural como casa común en su familia, escuela y comunidad para asumirlas y promoverlas.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) 
DO UPDATE SET 
    codigo = EXCLUDED.codigo,
    descriptor = EXCLUDED.descriptor,
    bloque = EXCLUDED.bloque,
    updated_at = NOW();
